!function(t){function m(m){for(var a,e,p=m[0],o=m[1],u=m[2],c=0,g=[];c<p.length;c++)e=p[c],Object.prototype.hasOwnProperty.call(n,e)&&n[e]&&g.push(n[e][0]),n[e]=0;for(a in o)Object.prototype.hasOwnProperty.call(o,a)&&(t[a]=o[a]);for(k&&k(m);g.length;)g.shift()();return i.push.apply(i,u||[]),r()}function r(){for(var t,m=0;m<i.length;m++){for(var r,e=i[m],p=!0,o=1;o<e.length;o++)r=e[o],0!==n[r]&&(p=!1);p&&(i.splice(m--,1),t=a(a.s=e[0]))}return t}function a(m){if(e[m])return e[m].exports;var r=e[m]={i:m,l:!1,exports:{}};return t[m].call(r.exports,r,r.exports,a),r.l=!0,r.exports}var e={},n={13:0},i=[];a.m=t,a.c=e,a.d=function(t,m,r){a.o(t,m)||Object.defineProperty(t,m,{enumerable:!0,get:r})},a.r=function(t){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(t,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(t,"__esModule",{value:!0})},a.t=function(t,m){if(1&m&&(t=a(t)),8&m)return t;if(4&m&&"object"==typeof t&&t&&t.__esModule)return t;var r=Object.create(null);if(a.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:t}),2&m&&"string"!=typeof t)for(var e in t)a.d(r,e,function(m){return t[m]}.bind(null,e));return r},a.n=function(t){var m=t&&t.__esModule?function(){return t.default}:function(){return t};return a.d(m,"a",m),m},a.o=function(t,m){return Object.prototype.hasOwnProperty.call(t,m)},a.p="";var p=window.webpackJsonp=window.webpackJsonp||[],o=p.push.bind(p);p.push=m,p=p.slice();for(var u=0;u<p.length;u++)m(p[u]);var k=o;i.push([14,0]),r()}({14:function(t,m,r){"use strict";r.r(m);var a=r(0);Object(a.a)("uk","army",r(16),r(1))},16:function(t){t.exports=JSON.parse('{"category":[{"name":"英国","link":"uk_shortcut"},{"name":"陆战武器","link":"uk_army"},{"name":"坦克","link":"uk_army#uk_army_tank"}],"model":"MK轻型坦克","description":"<h6>综述：</h6><p>英国是第一个发明坦克并将坦克首先运用到战争（第一次世界大战）中的国家。1938年，英国制造了大量的轻型坦克来替代骑兵作战，自1930年维克斯公司研发制造的MKⅠ轻型坦克服役开始，继后陆续开发了MKⅡ、MKⅡA、MKⅡB、MKⅢ、MKⅣ、MKⅤ、MKⅥ、MKⅥA、MKⅥB和MKⅥC；其中MKⅥB是英军在二战早期主要装备，战场使用率最高。当时，轻型坦克主要用途是支援步兵战斗，但轻型坦克火力和装甲防护都很弱，因此在战场上的战损率相当大，不过轻型坦克有较好的机动性，运输也方便，随着战争的发展，该类坦克已不适应战场的要求，除后期生产的MKVII（坦特拉克）曾作为空降坦克继续参加欧洲战场的战斗外，其余大多数则只能作训练和后方警卫用。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{text}}图中为MKⅡ的B轻型坦克，该坦克隶属澳大利亚第6机械化师，该部队1940年驻扎在北非战场的利比亚与埃及边界。MKⅡB轻型坦克坦克涂有沙漠伪装色，棕色和天蓝色是英国坦克最常见的沙漠涂装。{{image}}imgs/uk/army/uk_army_tankmk_11.jpg{{text}}1935年，在印度试验场作过沟机动检验的一辆MKⅡB轻型坦克，其车体轻，在崎岖路况时也有较好的机动性。{{image}}imgs/uk/army/uk_army_tankmk_12.jpg","description":"<h6>MKⅡ轻型坦克</h6><p>该型坦克重量轻，速度快，机动性较好，炮塔为正方形，不能转动；坦克只有一挺7.7mm口径机枪，车体装甲最厚也只有10mm，火力和防护力都十分薄弱，在战场上起不了多少作用；在1940北非战场的英军部队曾装备MKⅡA型和B型坦克，其余大多作训练用。</p><p>MKⅡB轻型坦克参数：</p><p>车重：4.5t，车速：48km/h，装甲厚度：4-10mm，武器：7.7mm口径机枪一挺，乘员：2人。</p>","caption":""},{"image":"imgs/uk/army/uk_army_tankmk_13.jpg","description":"<h6>MKⅢ轻型坦克</h6><p>该型坦克与Ⅱ型基本相同，但其车体与炮塔比Ⅱ型相对大些；该型坦克在1933年开始服役，主要作英军训练用。</p><p>坦克参数：</p><p>车重：4.5t，车速：48km/h，最大装甲厚度：12mm，武器：7.7mm或12.7mm口径机枪一挺，乘员：2人。</p>","caption":""},{"image":"imgs/uk/army/uk_army_tankmk_14.jpg","description":"<h6>MKⅣA轻型坦克</h6><p>该型坦克在1934年设计，其炮塔与车体相对上一型号有所改变，但坦克其它性能参数、武器配备则与MKⅢ基本相同。</p><p>该型坦克主要作海外英军训练用，也是未曾参加过实战。</p>","caption":""},{"image":"{{text}}1940年5月，在比利时，英军第3步兵师一辆MKⅥB轻型坦克。{{image}}imgs/uk/army/uk_army_tankmk_15.jpg{{text}}1940年末，在马耳他空军基地执行警卫任务的一辆不知所属单位的MKⅥB轻型坦克，坦克的涂装实在有个性。{{image}}imgs/uk/army/uk_army_tankmk_16.jpg","description":"<h6>MKⅥB轻型坦克</h6><p>MKⅥ轻型坦克有A、B和C型，其中MKⅥB是MK系列轻型坦克生产数量最多的，也是英军应用最广泛的轻型坦克。它车速更高，行动敏捷，也很可靠，但火力和防护仍然很薄弱，难以担当大任。</p><p>坦克参数：</p><p>车长：3.95m，车宽：约2m，车高：2.22m，车重：5t，车速：56km/h，装甲厚度：4-14mm，武器：一挺12.7mm口径双管机枪和一挺7.7mm（或7.92mm）口径机枪，乘员：3人。</p>","caption":""},{"image":"{{text}}MKVII轻型坦克{{image}}imgs/uk/army/uk_army_tankmk_17.jpg{{text}}1944年6月，在法国诺曼底战场，隶属英军第6空降师的一辆MKVII轻型坦克。注意该型坦克的传动装置与前面型号的不同。{{image}}imgs/uk/army/uk_army_tankmk_18.jpg","description":"<h6>MKVII轻型坦克</h6><p>该型坦克代号为“领主”，也有根据译音称“坦特拉克”，该型坦克安装了新型传动装置，使履带运行更加灵活。改装了一门约40mm口径（2磅）火炮，后期生产的部分坦克还改装了76.2mm口径的榴弹炮。这款坦克还曾被英军空降部队使用。</p><p>坦克参数：</p><p>车长：4.1m，车宽：2.3m，车高：2.1m，车重：7.5t，车速：37km/h，最大装甲厚度：16mm，武器：一门2磅火炮，一挺7.92mm口径机枪，乘员：3人。</p>","caption":""}],"part2title":"战场上的MK系列轻型坦克","part2description":"<p>二战初期，英国远征军配备的坦克基本上都是MKⅥ轻型坦克，但在德军的坦克闪电攻势下，战损极为严重，其中在法国服役的550辆MKⅥ轻型坦克，基本全部在战斗中损失和丢弃，最后只剩下6辆。此后在北非战场，英军装备的MKⅥB轻型坦克也曾在托布鲁克参战，但只是作迷惑德军用。1941年，澳大利亚部队也曾在敍利亚使用过这型坦克，此后该型坦克在希腊和马耳他等地，主要作清理空军机场跑道、警卫等用。而MKVII轻型坦克一共只生产了177辆，刚生产出来就装备给英军装甲部队投入使用，1944年6月在诺曼底登陆后，这些坦克用滑翔机装载越过英吉利海峡到达法国，给空军装甲兵使用。1942年5月，一支英军空降兵中队在进攻马达加斯加时也使用过这种坦克。</p>","part2content":[{"image":"imgs/uk/army/uk_army_tankmk_31.jpg","description":"1937年，在战争部门登记为“T648”编号，并具有民用牌照“CMM804”和“HX6962”的两辆MKⅤ轻型坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankmk_32.jpg","description":"正在运往法国的英国皇家坦克团2营的MKⅥB轻型坦克及车组成员。","caption":""},{"image":"imgs/uk/army/uk_army_tankmk_33.jpg","description":"1941年，在英国某机场，一辆MKⅥ坦克正在执行巡逻任务。","caption":""},{"image":"imgs/uk/army/uk_army_tankmk_34.jpg","description":"1940年6月，英军某皇家枪骑兵团遗弃在法国战场的一辆MKⅥC轻型坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankmk_35.jpg","description":"1940年，法国，正在参加演习的英军MKⅥB轻型坦克和人员运输车。","caption":""},{"image":"imgs/uk/army/uk_army_tankmk_36.jpg","description":"一辆MKⅥB轻型坦克下在英国一基地进行训练。","caption":""},{"image":"imgs/uk/army/uk_army_tankmk_37.jpg","description":"英军第3皇家坦克团在撒回英国时，遗弃在法国敦刻尔克海滩上的两辆MKⅥB轻型坦克。","caption":""},{"image":"imgs/uk/army/uk_army_tankmk_38.jpg","description":"这是MK系列最后一款轻型坦克MKVIII（哈里·霍普金），但只有少量装备了英军。","caption":""},{"image":"imgs/uk/army/uk_army_tankmk_39.jpg","description":"1945年，MKVII“坦特拉克”轻型坦克跟随英军空降部队在德国参加了横渡莱茵河的战斗。","caption":""}]}')}});